  (gen_random_uuid(), 'ai.use', 'Use AI drafting and summaries', true),
  (gen_random_uuid(), 'ai.killswitch', 'Disable AI features', false),
  (gen_random_uuid(), 'admin.users', 'Manage users and roles', false),
  (gen_random_uuid(), 'admin.config', 'Practice configuration', false),
  (gen_random_uuid(), 'audit.review', 'Review audit and break-the-glass reports', false),
  (gen_random_uuid(), 'export.deidentified', 'Run de-identified exports', false)
INSERT INTO role (id, tenant_id, code, name, is_system) VALUES (gen_random_uuid(), NULL, 'clinician', 'Clinician', true) ON CONFLICT DO NOTHING;
INSERT INTO role_permission (role_id, permission_id, tenant_id) SELECT r.id, p.id, NULL FROM role r, permission p WHERE r.tenant_id IS NULL AND r.code = 'clinician' AND p.code IN ('patient.read', 'patient.write', 'note.write', 'note.sign', 'note.cosign', 'order.create', 'result.acknowledge', 'result.release', 'rx.prescribe', 'rx.override_alert', 'ai.use', 'chart.break_glass') ON CONFLICT DO NOTHING;
